'use strict';
window.OrthodoxChurchGuide=(()=>{
  let promise,cleanup=()=>{};
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paragraphs=v=>String(v||'').split(/\n\s*\n/).map(p=>'<p>'+esc(p).replace(/\n/g,'<br>')+'</p>').join('');
  const safe=v=>{try{const u=new URL(v);return u.protocol==='https:'?esc(u.href):'#';}catch{return '#';}};
  const refs=b=>b.sourceRefs?.length?b.sourceRefs:b.sourceId?[{sourceId:b.sourceId,locator:b.locator}]:[];
  const meta=s=>[s.author,s.work||s.title,s.edition,s.translator].filter(Boolean).map(esc).join(' · ');
  async function load(){return promise||(promise=Promise.all(['church-interior.json','icon-images.json'].map(async file=>{const r=await (window.OrthodoxResources?window.OrthodoxResources.json('content/'+file).then(value=>({ok:true,json:async()=>value})):fetch('content/'+file));if(!r.ok)throw new Error('The church guide could not be loaded.');return r.json();})).then(([data,images])=>({...data,images:new Map(images.images.map(image=>[image.iconId,image]))})).catch(e=>{promise=null;throw e;}));}
  function unmount(){cleanup();cleanup=()=>{};window.ScripturePreviews?.close();window.GlossaryPreviews?.close();}
  async function mount(ctx){
    unmount();const {root,params=new URLSearchParams()}=ctx,controller=new AbortController(),signal=controller.signal;cleanup=()=>controller.abort();root.innerHTML='<p role="status">Loading church guide…</p>';
    let data;try{data=await load();}catch{if(signal.aborted)return;root.innerHTML='<h1>Inside the church</h1><p>The church guide could not be loaded.</p><button class="secondary" data-church-retry>Try again</button>';root.querySelector('button').onclick=()=>mount(ctx);return;}if(signal.aborted||!root.isConnected)return;
    const parts=new Map(data.parts.map(p=>[p.id,p])),sources=new Map(data.sources.map(s=>[s.id,s])),numbers=new Map(data.sources.map((s,i)=>[s.id,i+1]));
    const modes=['explore','liturgy','visitor'],views=['plan','iconostasis','objects'];
    let mode=modes.includes(params.get('mode'))?params.get('mode'):'explore',view=views.includes(params.get('view'))?params.get('view'):'plan',partId=parts.has(params.get('part'))?params.get('part'):data.parts[0].id,large=false;
    const liturgy=data.steps||[],visitors=data.visitorSteps||[];let stepId=params.get('step')||'',requestedPassage=params.get('passage')||'';
    const series=()=>mode==='visitor'?visitors:liturgy;
    const step=()=>series().find(s=>s.id===stepId)||series()[0];
    if(mode!=='explore'&&!parts.has(params.get('part')))partId=step()?.partIds?.find(id=>parts.has(id))||partId;
    const editionNotes=[...(data.layoutNotes||[]),...(data.notes||[])].filter((note,index,all)=>all.findIndex(item=>item.text===note.text)===index);
    function citations(block){return refs(block).map(ref=>'<a href="#church-source-'+esc(ref.sourceId)+'" data-church-source="'+esc(ref.sourceId)+'" aria-label="Source '+numbers.get(ref.sourceId)+'">['+numbers.get(ref.sourceId)+']</a> '+esc(ref.locator||'')).join(' · ');}
    function block(b,scope){const source=sources.get(refs(b)[0]?.sourceId);return '<div class="church-block" data-church-kind="'+esc(b.kind)+'" data-study-scope="church-'+esc(scope)+'"'+(source?' data-scripture-source="'+esc(source.id)+'"':'')+(b.edition==='kjv'?' data-scripture-edition="kjv"':'')+'>'+(b.kind==='quotation'?'<blockquote class="quoted-reading">'+paragraphs(b.text)+'</blockquote>':'<div class="church-summary">'+paragraphs(b.text)+'</div>')+(b.context?'<p class="reading-context">'+esc(b.context)+'</p>':'')+'<p class="church-citations">'+citations(b)+'</p></div>';}
    const name=id=>parts.get(id)?.title||id;
    function spot(id,shape,label,x,y){if(!parts.has(id))return '';return '<g class="spot" data-church-part="'+esc(id)+'" role="button" tabindex="0" aria-label="'+esc(name(id))+'"><title>'+esc(name(id))+'</title>'+shape+(label?'<text class="diagram-label" x="'+x+'" y="'+y+'" text-anchor="middle">'+esc(label)+'</text>':'')+'</g>';}
    const rect=(x,y,w,h,r=5)=>'<rect class="spot-fill" x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="'+r+'"/>';
    const picture=(id,x,y,w,h)=>{const path=data.images.get(id)?.path;return path&&/^assets\/(?:icons|saints)\/[a-z0-9-]+\.(?:jpg|png|webp|jpeg)$/.test(path)?'<image href="'+esc(path)+'" x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" preserveAspectRatio="xMidYMid meet"/>':'';};
    function plan(){return '<svg class="church-model" viewBox="0 0 560 770" role="group" aria-label="Illustrative Russian-style church plan"><defs><pattern id="church-floor" width="34" height="34" patternUnits="userSpaceOnUse"><path d="M0 0H34V34" fill="none" stroke="#d8cbb1" stroke-width=".6"/></pattern><radialGradient id="apse-wash"><stop stop-color="#e9d28f"/><stop offset="1" stop-color="#f5e8c5"/></radialGradient></defs><rect width="560" height="770" fill="#fcf9ef"/><text class="east-label" x="280" y="30" text-anchor="middle">LITURGICAL EAST</text><path d="M90 740V190Q90 58 280 58Q470 58 470 190V740H90Z" class="wall"/><path d="M100 730V190Q100 69 280 69Q460 69 460 190V730H100Z" class="wall-inner"/><path d="M101 190Q101 70 280 70Q459 70 459 190V291H101Z" fill="url(#apse-wash)"/><rect x="101" y="305" width="358" height="315" fill="url(#church-floor)"/><rect x="101" y="625" width="358" height="105" fill="#eee6d4"/><path d="M101 624H459" stroke="#ac9b71" stroke-width="2"/>'+spot('sanctuary',rect(105,75,350,212),'Sanctuary',280,104)+spot('apse',rect(186,72,188,67),'Apse',280,129)+'<path class="furniture" d="M255 146H305V160H255Z"/>'+spot('bishop-seat',rect(246,139,68,30),'',0,0)+'<rect class="furniture" x="238" y="179" width="84" height="65" rx="3"/><rect class="fabric" x="244" y="185" width="72" height="53" rx="2"/><path d="M275 198V224M264 207H286" stroke="#e6cd87" stroke-width="2"/>'+spot('holy-table',rect(231,172,98,80),'Holy Table',280,264)+'<rect class="furniture" x="123" y="187" width="55" height="42" rx="2"/>'+spot('prothesis',rect(116,175,72,72),'Prothesis',152,250)+'<path d="M105 291H455" stroke="#8f6f35" stroke-width="10"/><path d="M105 298H455" stroke="#cdb678" stroke-width="3"/>'+spot('iconostasis',rect(104,278,352,34),'',0,0)+spot('north-door',rect(137,276,44,41),'',0,0)+spot('south-door',rect(379,276,44,41),'',0,0)+spot('royal-doors',rect(250,276,60,41),'Royal Doors',280,337)+spot('theotokos-icon',rect(190,276,48,40),'',0,0)+spot('christ-icon',rect(322,276,48,40),'',0,0)+spot('patron-icon',rect(426,275,27,40),'',0,0)+'<path d="M113 349H447" stroke="#bbac84" stroke-width="2"/>'+spot('solea',rect(106,317,348,48),'',0,0)+'<path class="furniture" d="M246 350H314Q308 378 280 379Q252 378 246 350Z"/>'+spot('ambo',rect(242,346,76,42),'Ambo',280,401)+spot('nave',rect(171,412,218,165),'Nave',280,498)+spot('dome','<ellipse class="spot-fill" cx="280" cy="443" rx="83" ry="25"/>','Dome · overhead',280,448)+'<path d="M119 382H154V449H119ZM406 382H441V449H406Z" fill="#dce2cf" stroke="#aab38f"/>'+spot('north-kliros',rect(113,376,48,81),'Choir',138,469)+spot('south-kliros',rect(400,376,48,81),'Choir',424,469)+'<path class="furniture" d="M241 550L286 541L302 572L255 583Z"/>'+spot('analogion',rect(232,535,80,63),'Icon stand',273,611)+'<circle cx="150" cy="568" r="17" fill="#c5a65c" stroke="#8f743b"/><path d="M141 557V538M150 555V532M159 557V538" stroke="#ac742d" stroke-width="2"/>'+spot('candles',rect(121,523,58,69),'Candles',150,611)+'<ellipse cx="412" cy="555" rx="23" ry="12" class="furniture"/><path d="M395 556L402 578H422L429 556" class="furniture"/>'+spot('font',rect(382,535,63,59),'Font',413,611)+spot('narthex',rect(185,642,187,70),'Narthex',278,678)+'<path d="M251 736H310" stroke="#fcf9ef" stroke-width="10"/><path d="M252 737L269 714M309 737L292 714" fill="none" stroke="#9b8753" stroke-width="1.5"/><text class="diagram-small" x="280" y="762" text-anchor="middle">Entrance</text></svg>';}
    function iconostasis(){return '<svg class="church-model" viewBox="0 0 650 490" role="group" aria-label="Illustrative iconostasis with sample icons"><rect width="650" height="490" fill="#fcf9ef"/><path d="M28 395V150Q28 120 74 120H245Q305 42 365 120H576Q622 120 622 150V395Z" fill="#e3c995" stroke="#94733b" stroke-width="3"/><path d="M34 389V151Q34 127 74 127H249Q305 55 361 127H576Q616 127 616 151V389Z" fill="none" stroke="#f9edc8" stroke-width="2"/><path d="M305 62V27M290 39H320" stroke="#9b7c3b" stroke-width="4"/>'+spot('iconostasis',rect(34,120,542,35),'Iconostasis',305,150)+'<path d="M263 387V210Q305 169 347 210V387Z" class="fabric"/><path d="M305 190V387M277 227H333" stroke="#e9d69e" stroke-width="2"/>'+spot('royal-doors',rect(259,182,92,210),'Royal Doors',305,429)+'<rect x="61" y="208" width="49" height="180" class="fabric"/>'+spot('north-door',rect(57,202,58,190),'North door',86,450)+'<rect x="495" y="208" width="49" height="180" class="fabric"/>'+spot('south-door',rect(491,202,58,190),'South door',519,450)+'<rect class="wall-inner" x="133" y="188" width="101" height="164"/>'+picture('theotokos-vladimir',137,192,93,156)+spot('theotokos-icon',rect(129,184,109,174),'Theotokos',183,378)+'<rect class="wall-inner" x="370" y="188" width="101" height="164"/>'+picture('christ-pantocrator',374,192,93,156)+spot('christ-icon',rect(366,184,109,174),'Christ',420,378)+'<rect class="wall-inner" x="554" y="188" width="57" height="164"/>'+picture('saint-nicholas',557,192,51,156)+spot('patron-icon',rect(550,184,65,174),'Patron',582,378)+'<text class="diagram-small" x="582" y="400" text-anchor="middle">Example</text>'+'<text class="diagram-caption" x="305" y="475" text-anchor="middle">View from the nave · sample images</text></svg>';}
    function objectShape(id,x,y){
      const paths={
        'chalice':'M-35 -20Q-29 12 0 12Q29 12 35 -20ZM0 12V37M-23 39H23',
        'diskos':'M-45 -7Q0 10 45 -7M-42 -7Q0 -22 42 -7M0 3V28M-25 31H25',
        'star':'M-38 17Q0 -38 38 17M-24 26Q0 -36 24 26M0 -11V-28M-8 -20H8',
        'spear':'M-30 34L22 -25M12 -16L23 -40L33 -30L22 -25',
        'veils':'M-44 -18L25 -27L44 23L-29 33ZM-19 -7L18 -12M-10 16L25 10',
        'communion-spoon':'M-32 36L19 -18M17 -18Q8 -33 18 -40Q29 -45 34 -35Q38 -25 25 -18Z',
        'censer':'M-27 -24L-17 22H17L27 -24M0 -35V18M-24 22Q0 48 24 22M-14 18H14M-9 -36Q0 -48 9 -36',
        'altar-cross':'M-9 -43H9V-16H33V1H9V39H-9V1H-33V-16H-9Z',
        'altar-gospel':'M-32 -42H28L36 -35V37H-32ZM-24 -34H27M-20 28H25M0 -19V16M-12 -7H12',
        'tabernacle':'M-34 35V-8H34V35ZM-43 -8L0 -40L43 -8M-12 35V9Q0 -6 12 9V35M0 -40V-54M-6 -48H6',
        'antimension':'M-44 -33H44V33H-44ZM-37 -26H37V26H-37M0 -18V19M-14 -5H14'
      };
      return '<g transform="translate('+x+' '+y+')"><path d="'+(paths[id]||'M-34 -30H34V30H-34Z')+'" fill="none" stroke="#9b7b3d" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/></g>';
    }
    function objects(){const ids=data.parts.filter(p=>p.parentPartId||p.id==='censer');return '<svg class="church-model" viewBox="0 0 560 '+Math.max(280,Math.ceil(ids.length/2)*170+35)+'" role="group" aria-label="Schematic sacred objects, not an arrangement on the altar">'+ids.map((part,index)=>{const x=index%2*265+20,y=Math.floor(index/2)*170+20;return '<g><rect x="'+x+'" y="'+y+'" width="250" height="155" rx="5" fill="#f5edda" stroke="#c7b483"/>'+objectShape(part.id,x+125,y+65)+spot(part.id,rect(x+3,y+3,244,149),'',0,0)+'<text x="'+(x+125)+'" y="'+(y+137)+'" class="diagram-label" text-anchor="middle">'+esc(part.title)+'</text></g>';}).join('')+'</svg>';}
    function updateURL(){const q=new URLSearchParams();if(mode!=='explore')q.set('mode',mode);if(view!=='plan')q.set('view',view);q.set('part',partId);if(mode!=='explore'&&step())q.set('step',step().id);if(requestedPassage)q.set('passage',requestedPassage);history.replaceState(null,'','#/church'+(q.size?'?'+q:''));}
    function entryPoints(){const choices=[['explore','Explore the space',data.parts.length+' places and objects','Choose any point on the plan.'],['liturgy','Follow the Divine Liturgy',liturgy.length+' published moments','Move through the sequence in order.'],['visitor','Read the visitor guide',visitors.length+' published topics','Start with practical source readings.']];return '<section class="church-entry-points" aria-labelledby="church-entry-title"><div class="church-entry-heading"><p class="eyebrow">Start here</p><h2 id="church-entry-title">Choose one way in</h2><p>Each path opens the same source-rich guide from a different starting point.</p></div><div class="church-entry-list">'+choices.map(([id,title,count,description],index)=>'<button type="button" class="church-entry" data-church-mode="'+id+'" aria-pressed="'+(id===mode)+'"><span class="church-entry-number">0'+(index+1)+'</span><span><strong>'+esc(title)+'</strong><small>'+esc(description)+'</small></span><span class="church-entry-count">'+esc(count)+'</span></button>').join('')+'</div></section>';}
    function mapControls(){return '<div class="church-map-controls"><p class="eyebrow">Map controls</p><div><label>Diagram<select id="church-view">'+[['plan','Floor plan'],['iconostasis','Iconostasis'],['objects','Objects']].map(([id,label])=>'<option value="'+id+'"'+(id===view?' selected':'')+'>'+label+'</option>').join('')+'</select></label><label>Place or object<select id="church-part">'+data.parts.map(p=>'<option value="'+esc(p.id)+'"'+(p.id===partId?' selected':'')+'>'+esc(p.title)+'</option>').join('')+'</select></label></div></div>';}
    function sequenceGuide(){if(mode==='explore'||!step())return '';const entries=series(),current=step(),index=entries.indexOf(current),previous=entries[index-1],next=entries[index+1],label=mode==='liturgy'?'Divine Liturgy':'Published visitor guidance';return '<section class="church-sequence" id="church-journey" aria-labelledby="church-sequence-title"><div class="church-sequence-copy"><p class="eyebrow">'+label+'</p><h2 id="church-sequence-title">'+esc(current.title)+'</h2><p>Previous and Next update both the highlighted location and the source reading below.</p></div><div class="church-sequence-progress"><span>Reading '+(index+1)+' of '+entries.length+'</span><div aria-hidden="true"><i style="width:'+Math.round((index+1)/entries.length*100)+'%"></i></div></div><label class="church-sequence-jump">Jump to a reading<select id="church-step">'+entries.map((s,i)=>'<option value="'+esc(s.id)+'"'+(s.id===stepId?' selected':'')+'>'+(i+1)+'. '+esc(s.title)+'</option>').join('')+'</select></label><div class="church-sequence-actions" data-step-location="journey"><button type="button" class="secondary" data-church-step="previous"'+(!previous?' disabled':'')+'><span>Previous</span><strong>'+esc(previous?.title||'Start of guide')+'</strong></button><button type="button" class="secondary" data-church-step="next"'+(!next?' disabled':'')+'><span>Next</span><strong>'+esc(next?.title||'End of guide')+'</strong></button></div></section>';}
    function readingNavigation(){if(mode==='explore'||!step())return '';const entries=series(),index=entries.indexOf(step()),previous=entries[index-1],next=entries[index+1];return '<nav class="church-reading-navigation" data-step-location="reading" aria-label="Continue this guide"><button type="button" class="text-button" data-church-step="previous"'+(!previous?' disabled':'')+'><span>Previous</span><strong>'+esc(previous?.title||'Start of guide')+'</strong></button><span class="church-step-counter">Reading '+(index+1)+' of '+entries.length+'</span><button type="button" class="text-button" data-church-step="next"'+(!next?' disabled':'')+'><span>Next</span><strong>'+esc(next?.title||'End of guide')+'</strong></button></nav>';}
    function partDetail(part){return '<section data-church-selected-part="'+esc(part.id)+'"><h2>'+esc(part.title)+'</h2>'+(part.blocks||[]).map((b,i)=>block(b,part.id+'-'+i)).join('')+'</section>';}
    function detail(){const selected=parts.get(partId);if(mode==='explore')return '<p class="eyebrow">Selected place or object</p>'+partDetail(selected);const current=step();if(!current)return '<h2>No published steps available</h2>';const entries=series(),index=entries.indexOf(current);return '<p class="sr-only" role="status">Current reading: '+esc(current.title)+'</p><section class="church-step-header" data-church-selected-step="'+esc(current.id)+'"><p class="eyebrow">Reading '+(index+1)+' of '+entries.length+'</p><h2>'+esc(current.title)+'</h2>'+(current.performer?'<p class="church-performer">'+esc(current.performer)+'</p>':'')+(current.localCustom?'<p class="church-local-custom">'+esc(current.localCustom)+'</p>':'')+(current.simultaneousWith?.length?'<p class="church-parallel">Alongside: '+current.simultaneousWith.map(id=>{const other=liturgy.find(item=>item.id===id);return other?'<button type="button" class="text-button" data-church-goto-step="'+esc(id)+'">'+esc(other.title)+'</button>':'';}).join(' · ')+'</p>':'')+'</section>'+(current.blocks||[]).map((b,i)=>block(b,current.id+'-'+i)).join('')+'<div class="church-location-buttons">'+(current.partIds||[]).filter(id=>parts.has(id)).map(id=>'<button class="secondary" type="button" data-church-select="'+esc(id)+'" aria-pressed="'+(partId===id)+'">'+esc(name(id))+'</button>').join('')+'</div><details'+((current.partIds||[]).includes(partId)?' open':'')+'><summary>Selected place or object</summary>'+partDetail(selected)+'</details>'+readingNavigation();}
    function render(){
      window.ScripturePreviews?.close();window.GlossaryPreviews?.close();
      document.getElementById('passage-selection-toolbar')?.remove();
      const entries=series(),current=step();if(mode!=='explore'&&current)stepId=current.id;
      root.innerHTML='<article class="church-guide"><header class="church-guide-intro page-heading"><p class="eyebrow">A visual source guide</p><h1>Inside the church</h1><p class="lead">Browse one place, follow the Divine Liturgy in order, or begin with published guidance for a church visit.</p></header>'+entryPoints()+'<nav class="church-preview-links" aria-label="Related study"><span>Go deeper</span><a href="#/authority">Church authority</a><a href="#/services">Service texts</a><a href="#/learn?q=liturgy">Liturgy readings</a></nav>'+sequenceGuide()+'<div class="church-layout"><div class="church-model-panel church-panel-'+view+'" id="church-model"><div class="church-model-title">'+({plan:'Illustrative Russian-style arrangement',iconostasis:'Iconostasis · view from the nave',objects:'Objects · study index'})[view]+'</div>'+mapControls()+'<a class="church-focus-link" href="#church-detail" data-church-read>Read '+esc(name(partId))+' description</a><div class="church-model-viewport church-view-'+view+(large?' large':'')+'">'+({plan:plan,iconostasis,objects})[view]()+'</div>'+(view==='iconostasis'?'<details class="church-model-credits"><summary>Sample icon images and credits</summary>'+['theotokos-vladimir','christ-pantocrator','saint-nicholas'].map(id=>{const image=data.images.get(id);return image?'<p><a href="#/icon/'+esc(id)+'">'+esc(image.title)+'</a><br>'+window.OrthodoxVisuals.credit(image)+'</p>':'';}).join('')+'</details>':'')+'<div class="church-zoom"><button class="text-button" type="button" data-church-zoom aria-pressed="'+large+'">'+(large?'Fit diagram':'Enlarge diagram')+'</button></div><div class="church-symbol-key"><span>Selected part</span><span>Current step</span></div><p class="church-model-note">Illustration for this guide; positions and proportions are approximate. Select a place to read its published description.</p></div><article class="church-detail" id="church-detail" tabindex="-1"><a class="church-focus-link" href="#church-model" data-church-show-model>View diagram and map controls</a>'+detail()+'</article></div>'+(editionNotes.length?'<section><h2>Edition and layout notes</h2>'+editionNotes.map((b,i)=>block(b,'edition-'+i)).join('')+'</section>':'')+'<details class="church-parts-index"><summary>All places and objects ('+data.parts.length+')</summary><div class="church-parts-list">'+data.parts.map(p=>'<button class="secondary" data-church-select="'+esc(p.id)+'" type="button">'+esc(p.title)+'</button>').join('')+'</div></details><section class="church-guide-sources"><h2>Sources</h2><ol>'+data.sources.map(s=>'<li id="church-source-'+esc(s.id)+'" tabindex="-1"><a href="'+safe(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a><p>'+meta(s)+'</p><p>'+esc([s.type,s.tradition].filter(Boolean).join(' · '))+'</p><p>'+esc(s.rights||'')+'</p>'+(s.rightsNote?'<p>'+esc(s.rightsNote)+'</p>':'')+'</li>').join('')+'</ol></section><details class="church-source-context"><summary>Source context</summary>'+[...new Set([...(data.context?[data.context]:[]),...data.parts.flatMap(p=>p.blocks||[]).filter(b=>b.kind==='summary').map(b=>b.reason).filter(Boolean)])].map(paragraphs).join('')+'</details></article>';
      root.querySelectorAll('[data-church-part]').forEach(el=>{const selected=el.dataset.churchPart===partId,active=mode!=='explore'&&(current?.partIds||[]).some(id=>id===el.dataset.churchPart||parts.get(id)?.parentPartId===el.dataset.churchPart);el.classList.toggle('selected',selected);el.classList.toggle('step-active',active);el.setAttribute('aria-pressed',String(selected));});updateURL();window.ScripturePreviews?.enhance(root);
    }
    function selectPart(id){if(!parts.has(id))return;requestedPassage='';partId=id;if(parts.get(id).parentPartId||id==='censer')view='objects';render();}
    root.addEventListener('click',e=>{
      const target=e.target.closest('[data-church-part],[data-church-select],[data-church-mode],[data-church-step],[data-church-source],[data-church-zoom],[data-church-read],[data-church-goto-step],[data-church-show-model]');if(!target)return;
      if(target.dataset.churchPart||target.dataset.churchSelect){selectPart(target.dataset.churchPart||target.dataset.churchSelect);return;}
      if(target.dataset.churchGotoStep){requestedPassage='';mode='liturgy';stepId=target.dataset.churchGotoStep;partId=step()?.partIds?.find(id=>parts.has(id))||partId;render();root.querySelector('#church-step').focus({preventScroll:true});return;}
      if(target.dataset.churchMode){requestedPassage='';mode=target.dataset.churchMode;if(mode!=='explore'){stepId=series()[0]?.id||'';partId=series()[0]?.partIds?.find(id=>parts.has(id))||partId;}render();return;}
      if(target.dataset.churchStep){const controlLocation=target.closest('[data-step-location]')?.dataset.stepLocation||'reading',anchor=controlLocation==='journey'?root.querySelector('#church-journey'):root.querySelector('#church-detail'),anchorTop=anchor?.getBoundingClientRect().top||0;const entries=series(),index=entries.indexOf(step())+(target.dataset.churchStep==='next'?1:-1),next=entries[index];if(next){requestedPassage='';stepId=next.id;partId=next.partIds?.find(id=>parts.has(id))||partId;render();const updatedAnchor=controlLocation==='journey'?root.querySelector('#church-journey'):root.querySelector('#church-detail'),delta=(updatedAnchor?.getBoundingClientRect().top||0)-anchorTop;if(Math.abs(delta)>.5)window.scrollBy(0,delta);const button=root.querySelector('[data-step-location="'+controlLocation+'"] [data-church-step="'+target.dataset.churchStep+'"]');if(controlLocation==='reading')updatedAnchor?.scrollIntoView({behavior:'smooth',block:'start'});if(button?.disabled)updatedAnchor?.focus({preventScroll:true});else button?.focus({preventScroll:true});}return;}
      if(target.hasAttribute('data-church-zoom')){large=!large;render();root.querySelector('[data-church-zoom]').focus({preventScroll:true});return;}
      e.preventDefault();const destination=target.hasAttribute('data-church-show-model')?root.querySelector('#church-model'):target.hasAttribute('data-church-read')?root.querySelector('#church-detail'):root.querySelector('#'+CSS.escape('church-source-'+target.dataset.churchSource));if(destination){destination.tabIndex=-1;destination.focus({preventScroll:true});destination.scrollIntoView({behavior:'smooth'});}
    },{signal});
    root.addEventListener('keydown',e=>{const t=e.target.closest('[data-church-part]');if(t&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selectPart(t.dataset.churchPart);root.querySelector('#church-part').focus({preventScroll:true});}},{signal});
    root.addEventListener('change',e=>{if(e.target.id==='church-view'){requestedPassage='';view=e.target.value;render();root.querySelector('#church-view').focus({preventScroll:true});}if(e.target.id==='church-part'){selectPart(e.target.value);root.querySelector('#church-part').focus({preventScroll:true});}if(e.target.id==='church-step'){const anchorTop=e.target.getBoundingClientRect().top;requestedPassage='';stepId=e.target.value;partId=step()?.partIds?.find(id=>parts.has(id))||partId;render();const next=root.querySelector('#church-step'),delta=next.getBoundingClientRect().top-anchorTop;if(Math.abs(delta)>.5)window.scrollBy(0,delta);next.focus({preventScroll:true});}},{signal});render();
  }
  return {load,mount,unmount};
})();
